  +zipCode : string
  +address : string
  +phoneNumber : string
  +website : string
  +openingHours : string
}

class Pizza {
  +name : string
  +crustStructure : string
  +price : float
}

class Order {
  +id : int
  +dateTime : datetime
  +latestDeliveryTime : time
  +numberOfPeople : int
}

class EntertainmentOrder extends Order {
  +entertainmentType : string
  +duration : int
}

